import React, { ComponentType, useRef, useState } from 'react';
import styled from 'styled-components';
import { CellProps } from 'react-table';
import { useForm } from 'react-hook-form';
import { Popover } from '@mui/material';
import { DefaultTableCell } from './default-table-cell';
import { Button } from './button';

const ClickableDiv = styled.div`
  cursor: pointer;
  text-overflow: ellipsis;
  overflow-x: hidden;
  height: 100%;
  width: 100%;
  display: flex;
  align-items: center;
`;

const Form = styled.form`
  padding: 10px 10px 5px 10px;
  margin-bottom: 0;
  display: flex;
  flex-direction: column;
`;

export type OnUpdateParams<T = any, K = any> = {
  originalEntity: T;
  updatedData: K;
};

type CreateEditableCellComponentParams<T, K extends Partial<T>> = {
  FormInputs: any;
  onUpdate: (params: OnUpdateParams<T, K>) => void;
  displayText?: string;
  cellPlaceholder?: string;
};

export const createEditableCellComponent = <
  T extends Record<string, unknown>,
  K extends Partial<T>
>({
  onUpdate,
  FormInputs,
  displayText,
  cellPlaceholder,
}: CreateEditableCellComponentParams<T, K>): ComponentType<CellProps<any>> => (cellProps) => {
  const { row } = cellProps;
  const {
    handleSubmit,
    register,
    reset: resetForm,
    formState: { errors },
    control,
  } = useForm<K>({
    mode: 'onSubmit',
  });
  const [isOpen, setIsOpen] = useState<boolean>(false);
  const ref = useRef<HTMLDivElement>(null);

  const handleClick = () => {
    setIsOpen(true);
  };

  const handleClose = () => {
    setIsOpen(false);
    resetForm();
  };

  const id = isOpen ? 'simple-popover' : undefined;

  return (
    <>
      <ClickableDiv role="button" onClick={handleClick} tabIndex={-1}>
        <DefaultTableCell
          ref={ref}
          {...cellProps}
          displayText={displayText}
          cellPlaceholder={cellPlaceholder}
        />
      </ClickableDiv>
      <Popover
        id={id}
        open={isOpen}
        anchorEl={ref.current}
        onClose={handleClose}
        anchorOrigin={{
          vertical: 'bottom',
          horizontal: 'left',
        }}
      >
        <Form
          onSubmit={handleSubmit(async (updatedData: K) => {
            await onUpdate({ originalEntity: row.original, updatedData });
          })}
        >
          <FormInputs
            register={register}
            errors={errors}
            rowEntity={row.original}
            control={control}
          />
          <div style={{ display: 'flex', justifyContent: 'end' }}>
            <Button onClick={handleClose}>Cancel</Button>
            <Button type="submit">Save</Button>
          </div>
        </Form>
      </Popover>
    </>
  );
};
