import React, { ReactElement } from 'react';
import { Chip, SxProps } from '@mui/material';

interface CreateChipCellProps {
  text: string;
  backgroundColor: string;
  icon: ReactElement;
}

export const createChipCell = ({ text, backgroundColor, icon }: CreateChipCellProps) => {
  const sx: SxProps = {
    color: '#001C36',
    backgroundColor,
    fontSize: '12px',
    padding: '0 0.75rem 0 0.5rem',
    '& .MuiChip-label': { padding: 0 },
  };

  return <Chip sx={sx} size="small" label={text} icon={icon} />;
};
