import React, { useCallback, useEffect, useMemo } from 'react';
import 'regenerator-runtime/runtime'; // needed for react-table
import {
  Row as ReactTableRow,
  useAsyncDebounce,
  useGlobalFilter,
  usePagination,
  useSortBy,
  useRowSelect,
  useTable,
} from 'react-table';
import { matchSorter } from 'match-sorter';
import './Table.less';
import { Paginator } from '../../molecules';
import { DefaultTableCell } from './default-table-cell';
import { TTable } from './t-table';
import { THead } from './t-head';
import { THeadRow } from './t-head-row';
import { THeadCell } from './t-head-cell';
import { Chevron } from './chevron';
import { TBody } from './t-body';
import { TBodyRow } from './t-body-row';
import { TBodyCell } from './t-body-cell';
import { TableEmptyMessage } from './table-empty-message';
import { Columns } from './types';
import { IndeterminateCheckbox } from './checkbox';
import { Loader } from '../../atoms';

export { createEditableCellComponent } from './create-editable-cell-component';
export { EllipsisTypography } from './ellipsis-typography';
export { createChipCell } from './create-chip-cell';

const TableProps = {};

interface Props<T extends Record<string, any>> {
  columns: Columns<T>[];
  data: T[];
  initialSortColumnNames: string[];
  globalFilterColumnNames: string[];
  filter: string;
  showPaginationBottom?: boolean;
  showRowSelection?: (selectedRows: unknown[]) => void;
  noDataMessage?: string;
  noResultsFoundInSearchMessage?: string;
  loading: boolean;
  disableSortBy?: boolean;
  pageSize?: number;
}

const Table = <T extends Record<string, any>>({
  columns,
  data,
  initialSortColumnNames,
  globalFilterColumnNames,
  filter,
  loading,
  showPaginationBottom = true,
  showRowSelection,
  noDataMessage = 'This table is currently empty',
  noResultsFoundInSearchMessage = 'No results found',
  disableSortBy,
  pageSize = 9,
}: Props<T>) => {
  const globalFilterByColumnNames = useCallback(
    (rows: ReactTableRow<T>[], _, query: string) =>
      matchSorter(rows, query, {
        keys: globalFilterColumnNames.map((columnName) => `values.${columnName}`),
      }),
    [globalFilterColumnNames],
  );

  const memoizedData = useMemo(() => data, [data]);
  const sortBy = useMemo(() => initialSortColumnNames.map((columnName) => ({ id: columnName })), [
    initialSortColumnNames,
  ]);

  const {
    getTableBodyProps,
    flatHeaders,
    page,
    prepareRow,
    pageCount,
    nextPage,
    previousPage,
    toggleAllPageRowsSelected,
    setGlobalFilter,
    rows,
    state: { pageIndex, selectedRowIds },
  } = useTable<T>(
    {
      columns,
      data: memoizedData,
      globalFilter: globalFilterByColumnNames,
      disableSortBy,
      initialState: { pageSize, pageIndex: 0, sortBy },
      defaultColumn: { Cell: DefaultTableCell },
    } as any,
    useGlobalFilter,
    useSortBy,
    usePagination,
    useRowSelect,
    (hooks) => {
      if (showRowSelection) {
        return hooks.visibleColumns.push((visibleColumns) => [
          {
            id: 'selection',
            maxWidth: 40,
            Header: ({
              getToggleAllRowsSelectedProps,
            }: {
              getToggleAllRowsSelectedProps: () => any;
            }) => <IndeterminateCheckbox {...getToggleAllRowsSelectedProps()} />,
            Cell: ({ row }) => <IndeterminateCheckbox {...row.getToggleRowSelectedProps()} />,
          },
          ...visibleColumns,
        ]);
      }

      return hooks.visibleColumns.push((visibleColumns) => [
        { id: 'non-selection-xx', maxWidth: 40, Cell: () => <span> </span> },
        ...visibleColumns,
      ]);
    },
  ) as any;

  useEffect(() => {
    if (showRowSelection) showRowSelection(selectedRowIds);
  }, [showRowSelection, selectedRowIds]);

  const debouncedSetGlobalFilter = useAsyncDebounce((globalFilter) => {
    setGlobalFilter(globalFilter || undefined);
    if (showRowSelection) toggleAllPageRowsSelected(false);
  }, 200);

  useEffect(() => {
    debouncedSetGlobalFilter(filter);
  }, [filter, debouncedSetGlobalFilter]);

  return (
    <TTable>
      <THead>
        <THeadRow>
          {flatHeaders.map((column: any) => (
            <THeadCell
              {...column.getHeaderProps(column.getSortByToggleProps({ style: column.style }))}
              minWidth={column.minWidth}
              maxWidth={column.maxWidth}
            >
              {column.render('Header')}
              {column.isSorted ? (
                <Chevron
                  className={`icon-chevron-${column.isSortedDesc ? 'down' : 'up'}`}
                  padding="0 0 0 10px"
                />
              ) : (
                ''
              )}
            </THeadCell>
          ))}
        </THeadRow>
      </THead>
      <TBody {...getTableBodyProps()} showPaginationBottom={showPaginationBottom}>
        {page.map((row: any) => {
          prepareRow(row);
          return (
            <TBodyRow
              {...row.getRowProps()}
              isFirst={row.index === pageIndex * pageSize}
              isLast={row.index === page.at(-1).index}
            >
              {row.cells.map((cell: any) => (
                <TBodyCell
                  {...cell.getCellProps({ style: cell.column.style })}
                  minWidth={cell.column.minWidth}
                  maxWidth={cell.column.maxWidth}
                >
                  {cell.render('Cell')}
                </TBodyCell>
              ))}
            </TBodyRow>
          );
        })}
      </TBody>
      {loading && <Loader />}
      {!loading && !!memoizedData?.length && !!rows.length && showPaginationBottom && (
        <Paginator
          pagesAmount={pageCount}
          page={pageCount > 0 ? pageIndex + 1 : 0}
          onNextPage={nextPage}
          onPreviousPage={previousPage}
          className="margin-top-20"
        />
      )}
      {!loading && !rows.length && (
        <TableEmptyMessage>
          {!memoizedData.length ? noDataMessage : noResultsFoundInSearchMessage}
        </TableEmptyMessage>
      )}
    </TTable>
  );
};

Table.propTypes = TableProps;
Table.defaultProps = {};

export default Table;
