import React, { forwardRef } from 'react';
import { CellProps } from 'react-table';
import styled from 'styled-components';

export const PlaceholderText = styled.span`
  color: rgb(130, 130, 130);
`;

export const DefaultTableCell = forwardRef<
  HTMLDivElement,
  CellProps<any> & { displayText?: string; cellPlaceholder?: string }
>(({ value, cell, displayText, cellPlaceholder }, ref) => {
  const cellKey = cell?.getCellProps()?.key;
  const textToDisplay = displayText || (Array.isArray(value) ? value.join(', ') : value);

  return (
    <>
      <div
        ref={ref}
        data-tip
        data-for={cellKey}
        key={cellKey}
        style={{ overflowX: 'hidden', textOverflow: 'ellipsis' }}
      >
        {textToDisplay || <PlaceholderText>{cellPlaceholder}</PlaceholderText>}
      </div>
    </>
  );
});
